const staticData = $getWorkflowStaticData('global');
const chatId = $json.message.chat.id.toString();
const text = $json.message.text || '';

if (!staticData.sessions) staticData.sessions = {};
if (!staticData.sessions[chatId]) staticData.sessions[chatId] = { step: 0, data: {} };

const session = staticData.sessions[chatId];
let response = '';
let sendToLucas = false;
let orderSummary = '';

if (text === '/start' || session.step === 0) {
  session.step = 1;
  response = 'Hola! Bienvenido a El Huerto de Lucas.\nPara hacer tu pedido necesito algunos datos.\n\nCual es tu nombre?';
} else if (session.step === 1) {
  session.data.name = text;
  session.step = 2;
  response = 'Gracias ' + text + '!\nQue productos queres pedir?\n(Ej: 2 atados de acelga, 1 docena de huevos)';
} else if (session.step === 2) {
  session.data.products = text;
  session.step = 3;
  response = 'Anotado!\nCual es tu direccion de entrega?';
} else if (session.step === 3) {
  session.data.address = text;
  session.step = 4;
  response = 'Perfecto!\nCual es tu numero de telefono?';
} else if (session.step === 4) {
  session.data.phone = text;
  orderSummary = 'NUEVO PEDIDO - El Huerto de Lucas\n\nNombre: ' + session.data.name + '\nProductos: ' + session.data.products + '\nDireccion: ' + session.data.address + '\nTelefono: ' + session.data.phone;
  response = 'Tu pedido fue recibido! Te vamos a contactar para confirmar la entrega. Gracias por elegirnos!';
  sendToLucas = true;
  staticData.sessions[chatId] = { step: 0, data: {} };
}

return [{ json: { chatId, response, sendToLucas, orderSummary } }];
